-- audit: one movement-like log line per quantity that changes
INSERT INTO log_entries (id, "timestamp", user_id, user_name, action, category, details)
SELECT lower(to_hex((extract(epoch from clock_timestamp()) * 1000)::bigint)) || substr(md5(r.id), 1, 9),
       to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
       coalesce(u.id, ''), 'Stefania Brambilla (inventory 10/2026)',
       'Corrected stock of ' || r.name, 'reagent',
       r.current_stock::text || ' ' || coalesce(r.unit, '') || ' → ' || c.stock::text || ' ' || c.unit
FROM   reagents r JOIN census_reagents c ON c.id = r.id AND c.name = r.name
LEFT   JOIN lab_users u ON lower(u.name) = 'stefania brambilla'
WHERE  r.current_stock IS DISTINCT FROM c.stock;

UPDATE reagents r
SET    current_stock   = c.stock,
       max_stock       = GREATEST(coalesce(r.max_stock, 0), c.stock),
       unit            = c.unit,
       expiry_date     = coalesce(c.expiry, r.expiry_date),
       alert_threshold = coalesce(c.thr, r.alert_threshold),
       notes           = CASE WHEN c.note IS NULL THEN r.notes
                              WHEN coalesce(r.notes, '') = '' THEN c.note
                              WHEN r.notes LIKE '%' || c.note || '%' THEN r.notes
                              ELSE r.notes || ' — ' || c.note END
FROM   census_reagents c
WHERE  c.id = r.id AND c.name = r.name;

