-- §2 −80 °C box 1 (sheet 5). Vials are matched by slot AND cell line,
--    so a vial moved in the app since the list was printed is left
--    alone and shows up in the check at the end.
-- ------------------------------------------------------------
-- 2a. The 29/09 restore test left A3 and D9 swapped on some copies of
--     the data; Stefania confirms A3 = A549, D9 = HT-29. Swap back if needed.
UPDATE cryo_vials v SET "row" = 3, col = 8
WHERE  v.box_id = 'sb-su-1790513907855-6-b1' AND v."row" = 0 AND v.col = 2 AND v.cell_line = 'HT-29'
  AND  EXISTS (SELECT 1 FROM cryo_vials x WHERE x.box_id = 'sb-su-1790513907855-6-b1' AND x."row" = 3 AND x.col = 8 AND x.cell_line = 'A549');
UPDATE cryo_vials v SET "row" = 0, col = 2
WHERE  v.box_id = 'sb-su-1790513907855-6-b1' AND v."row" = 3 AND v.col = 8 AND v.cell_line = 'A549'
  AND  NOT EXISTS (SELECT 1 FROM cryo_vials x WHERE x.box_id = 'sb-su-1790513907855-6-b1' AND x."row" = 0 AND x.col = 2);

