-- §1: how many log lines the census wrote today
SELECT count(*) AS census_log_lines FROM log_entries WHERE user_name LIKE 'Stefania Brambilla (inventory%' AND "timestamp" >= to_char(now() - interval '1 hour', 'YYYY-MM-DD"T"HH24:MI');
-- §2: the −80 box as it is now (expect 52 vials; no 'Unknown'; A3 = A549, D9 = HT-29)
SELECT chr(65 + "row") || (col + 1) AS slot, cell_line, passage, date, user_name
FROM   cryo_vials WHERE box_id = 'sb-su-1790513907855-6-b1' ORDER BY "row", col;
